//! **Architecture §6 step 3's named falsifier.**
//!
//! > *Falsified if: `vendor-verify.sh` fails or the pristine upstream verifier
//! > rejects a proof.*
//!
//! Every proof here is generated by the **signer**, through its own FFI, from
//! scalars produced by the **ruled** `r`/`ρ` derivation, and then handed to a
//! verifier built from **pristine upstream `85dbac7`** — a separate binary
//! linked against a separate library, communicating only in hex on argv. The
//! patched library is not in that process.
//!
//! # What this establishes, and where the claim stops
//!
//! It establishes that this signer's proofs are accepted by upstream's verifier
//! at the shapes tested — `n = 3` and `n = 4`, with a bound context. Because
//! `src/` and `include/` are byte-identical between tag `0.4.0-rc4` (the
//! version in rippled 3.3.0) and tag `1.0.4` (what we vendor) — asserted on
//! every run of `vendor-verify.sh`, not assumed — that verifier is the ledger's
//! verifier.
//!
//! **It is a test, not a proof.** A passing test at two participant counts is
//! not a statement about every input. The ledger's own acceptance is a separate
//! and stronger piece of evidence, and it lives in
//! `tools/spike-step3-2026-08-18/`.

use std::process::Command;
use wconf_signer::prover::{self, ConvertBackInputs, SendInputs};
use wconf_signer::randomness::{self, Inputs, TxKind};
use wconf_signer::store;

fn pristine() -> String {
    let path =
        std::env::var("WCONF_MPTOOL_PRISTINE").unwrap_or_else(|_| "/tmp/wconf/mptool-pristine".into());
    assert_pristine(&path);
    path
}

/// **Check that the binary is not the patched one.**
///
/// ⚠ **That is weaker than "it is pristine upstream", and the earlier wording
/// claimed the stronger thing.** Both round-two legs said so. This inspects a
/// symbol table: a patched build that was stripped, or that reached the patch
/// through a dynamically loaded library, would pass. What it does rule out is
/// the failure that actually threatened this milestone — `WCONF_MPTOOL_PRISTINE`
/// pointing at the patched `mptool` sitting next to it in the same directory,
/// which is one typo away and which nothing checked at all.
///
/// `REVIEW-015b`: the falsifier trusted a path. Point `WCONF_MPTOOL_PRISTINE`
/// at the *patched* `mptool` and every test in this file passes — including the
/// corrupted-proof test, which only shows the verifier is not a rubber stamp —
/// while the thing the milestone claims is no longer being tested at all.
///
/// `secp256k1_mpt_scalar_reduce64` is the wide reduction the W-CONF patch adds.
/// It exists in the patched library and **not** upstream, so its presence in
/// this binary's symbol table means the binary is not pristine.
fn assert_pristine(path: &str) {
    let out = Command::new("nm")
        .arg(path)
        .output()
        .unwrap_or_else(|e| panic!("cannot run nm on {path}: {e}"));
    assert!(out.status.success(), "nm failed on {path}");
    let symbols = String::from_utf8_lossy(&out.stdout);
    // A stripped binary yields few or no symbols, and "no symbols" would
    // satisfy an absence check trivially. Require a symbol table worth
    // inspecting before drawing any conclusion from it.
    let count = symbols.lines().count();
    assert!(
        count > 100,
        "{path} exposes only {count} symbols; it may be stripped, and an absence check \
         against a stripped binary concludes nothing"
    );
    assert!(
        !symbols.contains("secp256k1_mpt_scalar_reduce64"),
        "{path} contains `secp256k1_mpt_scalar_reduce64`, which exists only in the W-CONF \
         patch. This binary is NOT pristine upstream, so nothing in this file is testing \
         what it claims to test."
    );
    // And it must be a real mptool, not an empty file that trivially lacks the
    // symbol.
    assert!(
        symbols.contains("mpt_verify_send_proof"),
        "{path} does not export mpt_verify_send_proof; it is not an mptool build"
    );
}

/// Run the **pristine** verifier. Deliberately a separate process: it must not
/// be possible for the patched library to be what answers.
fn verify_with_pristine(args: &[String]) -> String {
    let bin = pristine();
    let out = Command::new(&bin).args(args).output().unwrap_or_else(|e| {
        panic!("cannot run the pristine verifier {bin}: {e}. Run tools/spike-2026-08-18/build.sh")
    });
    assert!(
        out.status.success(),
        "pristine mptool failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    String::from_utf8_lossy(&out.stdout).trim().to_string()
}

/// Fresh entropy, exactly as the signing path draws it: 64 bytes per attempt.
fn entropy64() -> [u8; 64] {
    let mut e = [0u8; 64];
    store::getrandom(&mut e).expect("the OS CSPRNG is a prerequisite; r/rho abort without it");
    e
}

struct Fixture {
    sender: prover::ElGamalKeypair,
    destination: prover::ElGamalKeypair,
    issuer: prover::ElGamalKeypair,
    auditor: prover::ElGamalKeypair,
    account: [u8; 20],
    dest_account: [u8; 20],
    issuance: [u8; 24],
}

impl Fixture {
    /// ⚠ **Keys from the library's own generator** — the `standalone` source
    /// since step 6 named it, and still not the ruled derivation. This is step 3's
    /// explicit instruction and it is *not* the ruled keygen, which is step 6
    /// and still owes issues #10 and #11.
    fn new() -> Fixture {
        Fixture {
            sender: prover::ElGamalKeypair::generate().unwrap(),
            destination: prover::ElGamalKeypair::generate().unwrap(),
            issuer: prover::ElGamalKeypair::generate().unwrap(),
            auditor: prover::ElGamalKeypair::generate().unwrap(),
            account: [0x11; 20],
            dest_account: [0x22; 20],
            issuance: [0x33; 24],
        }
    }
}

/// Build a Send exactly as the signing path does, and return everything the
/// pristine verifier needs to check it.
fn prove_send(fx: &Fixture, amount: u64, balance: u64, with_auditor: bool) -> (Vec<String>, bool) {
    let sequence = 4242u32;
    let version = 7u32;
    let context =
        prover::send_context_hash(&fx.account, &fx.issuance, sequence, &fx.dest_account, version)
            .unwrap();

    // The ruled derivation. Not `mpt_generate_blinding_factor`.
    let e = entropy64();
    let inputs = Inputs {
        tx_kind: TxKind::Send,
        account_id: &fx.account,
        mpt_issuance_id: &fx.issuance,
        tx_context_id: &context,
        entropy64: &e,
    };
    let (r, rho) = randomness::derive_pair(&inputs).expect("entropy failure aborts; it must not here");

    // The sender's on-ledger balance ciphertext. In the live path this is read
    // from the ledger; its blinding is whatever produced it and is not ours.
    let balance_r = randomness::derive(
        &Inputs { entropy64: &entropy64(), ..inputs },
        randomness::Role::ElgamalR,
    )
    .unwrap();
    let balance_ciphertext = prover::encrypt(balance, fx.sender.public(), &balance_r).unwrap();

    let send = SendInputs {
        sk: fx.sender.secret(),
        pk: fx.sender.public(),
        amount,
        balance,
        balance_ciphertext,
        destination_pk: *fx.destination.public(),
        issuer_pk: *fx.issuer.public(),
        auditor_pk: if with_auditor { Some(*fx.auditor.public()) } else { None },
        context,
    };
    let material = prover::prepare_send(&send, &r, &rho).unwrap();
    let participants = material.participants(&send);

    // Our own library's opinion, recorded so the two can be compared.
    let ours = prover::verify_send_proof(
        &material.proof,
        &participants,
        &balance_ciphertext,
        &material.amount_commitment,
        &material.balance_commitment,
        &context,
    );

    let mut args = vec![
        "verify-send".to_string(),
        prover::hex(&material.proof),
        prover::hex(&balance_ciphertext),
        prover::hex(&material.amount_commitment),
        prover::hex(&material.balance_commitment),
        prover::hex(&context),
        participants.len().to_string(),
    ];
    for p in &participants {
        args.push(prover::hex(&p.pubkey));
        args.push(prover::hex(&p.ciphertext));
    }
    (args, ours)
}

#[test]
fn the_pristine_upstream_verifier_accepts_our_send_proof_at_n3() {
    let fx = Fixture::new();
    let (args, ours) = prove_send(&fx, 100, 900, false);
    assert!(ours, "our own library rejected our own proof");
    assert_eq!(verify_with_pristine(&args), "OK", "the pristine upstream verifier rejected it");
}

#[test]
fn the_pristine_upstream_verifier_accepts_our_send_proof_at_n4() {
    let fx = Fixture::new();
    let (args, ours) = prove_send(&fx, 1, 1, true);
    assert!(ours);
    assert_eq!(verify_with_pristine(&args), "OK");
}

/// A zero-amount Send is valid — `CLAIMS.md` E-22 — and it is the shape most
/// likely to expose a degenerate scalar path.
#[test]
fn the_pristine_upstream_verifier_accepts_a_zero_amount_send() {
    let fx = Fixture::new();
    let (args, ours) = prove_send(&fx, 0, 500, false);
    assert!(ours);
    assert_eq!(verify_with_pristine(&args), "OK");
}

/// The identity check has to be able to fail, or it is decoration.
///
/// Pointed at the **patched** `mptool`, `assert_pristine` must panic. Without
/// this, a check that silently never fires would look exactly like a check that
/// passes.
#[test]
#[should_panic(expected = "NOT pristine upstream")]
fn the_pristine_identity_check_rejects_the_patched_binary() {
    let patched =
        std::env::var("WCONF_MPTOOL").unwrap_or_else(|_| "/tmp/wconf/mptool-patched".into());
    assert_pristine(&patched);
}

/// The falsifier has to be able to fail.
///
/// A verifier that answers `OK` to everything would make every test above
/// vacuous — which is exactly the false-pass mode `REVIEW-009` §8 found in
/// `t-nbound.c`. Corrupt one byte of the proof and the same pristine verifier
/// must say `FAIL`.
#[test]
fn the_pristine_verifier_rejects_a_corrupted_proof() {
    let fx = Fixture::new();
    let (mut args, _) = prove_send(&fx, 100, 900, false);
    let proof = &mut args[1];
    // Flip the last nibble of the sigma section's first response.
    let mut bytes: Vec<char> = proof.chars().collect();
    bytes[9] = if bytes[9] == 'A' { 'B' } else { 'A' };
    *proof = bytes.into_iter().collect();
    assert_eq!(
        verify_with_pristine(&args),
        "FAIL",
        "the pristine verifier accepted a corrupted proof, so every other test here proves nothing"
    );
}

/// The Convert proof — a Schnorr PoK over the same context machinery.
#[test]
fn the_pristine_upstream_verifier_accepts_our_convert_proof() {
    let fx = Fixture::new();
    let context = prover::convert_context_hash(&fx.account, &fx.issuance, 9001).unwrap();
    let proof =
        prover::convert_proof(fx.sender.public(), fx.sender.secret(), &context).unwrap();
    assert!(prover::verify_convert_proof(&proof, fx.sender.public(), &context));
    let out = verify_with_pristine(&[
        "verify-convert".into(),
        prover::hex(&proof),
        prover::hex(fx.sender.public()),
        prover::hex(&context),
    ]);
    assert_eq!(out, "OK");
}

/// **The ConvertBack proof, in front of the pristine upstream verifier.**
///
/// ⚠ **The witness is `(b, ρ, sk_A)` — the BALANCE, not the amount** — and
/// `vendor-verify.sh` asserts that ordering independently by checking that
/// `proof_compact_convertback.c` passes `sk_offset=64` where every other
/// compact proof passes `0`. The 816 bytes are a 128-byte compact sigma proof
/// plus a 688-byte single Bulletproof over the **remainder** `b − m`.
fn prove_convert_back(
    fx: &Fixture,
    amount: u64,
    balance: u64,
    with_auditor: bool,
) -> (Vec<String>, bool, u64) {
    let sequence = 4242u32;
    let version = 7u32;
    let context =
        prover::convert_back_context_hash(&fx.account, &fx.issuance, sequence, version).unwrap();

    let e = entropy64();
    let inputs = Inputs {
        tx_kind: TxKind::ConvertBack,
        account_id: &fx.account,
        mpt_issuance_id: &fx.issuance,
        tx_context_id: &context,
        entropy64: &e,
    };
    let (r, rho) = randomness::derive_pair(&inputs).expect("entropy failure aborts; not here");

    // The on-ledger balance ciphertext, under randomness that is **not** ours —
    // the proof links it to `pc_b` through `sk_A`, not through its blinding.
    let balance_r = randomness::derive(
        &Inputs { entropy64: &entropy64(), ..inputs },
        randomness::Role::ElgamalR,
    )
    .unwrap();
    let balance_ciphertext = prover::encrypt(balance, fx.sender.public(), &balance_r).unwrap();

    let cb = ConvertBackInputs {
        sk: fx.sender.secret(),
        pk: fx.sender.public(),
        amount,
        balance,
        balance_ciphertext,
        issuer_pk: *fx.issuer.public(),
        auditor_pk: if with_auditor { Some(*fx.auditor.public()) } else { None },
        context,
    };
    let material = prover::prepare_convert_back(&cb, &r, &rho).unwrap();

    // **XLS-0096 §10.4.2 item 6, run with the published `r`.** This is the
    // non-ZKP half of what a validator checks: that `BlindingFactor`
    // reconstructs every ciphertext from the plaintext `MPTAmount`. It is
    // asserted here rather than in `tests/convert_back.rs` because it needs `r`
    // as a `Scalar`, and a `Scalar` is deliberately only ever the output of a
    // reduction — there is no constructor from bytes, and a test is not a
    // reason to add one.
    let holder = prover::Participant {
        pubkey: *fx.sender.public(),
        ciphertext: material.holder_ciphertext,
    };
    let issuer = prover::Participant {
        pubkey: *fx.issuer.public(),
        ciphertext: material.issuer_ciphertext,
    };
    let auditor = material.auditor_ciphertext.map(|ct| prover::Participant {
        pubkey: *fx.auditor.public(),
        ciphertext: ct,
    });
    assert!(
        prover::verify_revealed_amount(amount, &r, &holder, &issuer, auditor.as_ref()),
        "the published BlindingFactor does not reconstruct the ciphertexts from MPTAmount"
    );
    assert_eq!(
        material.blinding_factor,
        *r.as_bytes(),
        "the field that goes on chain is not the derived r"
    );

    let ours = prover::verify_convert_back_proof(
        &material.proof,
        fx.sender.public(),
        &balance_ciphertext,
        &material.balance_commitment,
        amount,
        &context,
    );

    let args = vec![
        "verify-convertback".to_string(),
        prover::hex(&material.proof),
        prover::hex(fx.sender.public()),
        prover::hex(&balance_ciphertext),
        prover::hex(&material.balance_commitment),
        amount.to_string(),
        prover::hex(&context),
    ];
    (args, ours, material.proof.len() as u64)
}

#[test]
fn the_pristine_upstream_verifier_accepts_our_convert_back_proof() {
    let fx = Fixture::new();
    let (args, ours, len) = prove_convert_back(&fx, 300, 900, false);
    assert_eq!(len, 816, "XLS-0096 §10.3 fixes the ZKProof at 816 bytes");
    assert!(ours, "our own library rejected our own proof");
    assert_eq!(verify_with_pristine(&args), "OK", "the pristine upstream verifier rejected it");
}

/// The remainder is **zero**, which is in range and must prove.
///
/// This is the facility's own wind-down shape — the Dedicated Account
/// converting its entire remaining float back — so a degenerate scalar path
/// here would be found by the first real retirement rather than by a test.
#[test]
fn the_pristine_upstream_verifier_accepts_a_convert_back_of_the_entire_balance() {
    let fx = Fixture::new();
    let (args, ours, _) = prove_convert_back(&fx, 500, 500, true);
    assert!(ours);
    assert_eq!(verify_with_pristine(&args), "OK");
}

/// The ConvertBack falsifier has to be able to fail, for the same reason the
/// Send one does: a verifier that answers `OK` to everything makes every
/// assertion above vacuous.
///
/// **Two ways, not one.** A corrupted proof, and a verifier told the *wrong
/// public amount* — the second is the sharper of the two, because it is the
/// binding the whole transaction rests on: `MPTAmount` is in the clear, and a
/// proof that did not bind it would let any amount be withdrawn against any
/// range proof.
#[test]
fn the_pristine_verifier_rejects_a_corrupted_or_misbound_convert_back() {
    let fx = Fixture::new();
    let (args, _, _) = prove_convert_back(&fx, 300, 900, false);

    let mut corrupted = args.clone();
    let mut chars: Vec<char> = corrupted[1].chars().collect();
    chars[9] = if chars[9] == 'A' { 'B' } else { 'A' };
    corrupted[1] = chars.into_iter().collect();
    assert_eq!(
        verify_with_pristine(&corrupted),
        "FAIL",
        "the pristine verifier accepted a corrupted ConvertBack proof"
    );

    let mut misbound = args;
    misbound[5] = "301".to_string();
    assert_eq!(
        verify_with_pristine(&misbound),
        "FAIL",
        "the proof does not bind MPTAmount — any amount could be withdrawn against it"
    );
}

/// A ConvertBack for more than the balance is refused **before** a proof is
/// generated, and with a message naming both numbers.
///
/// The library refuses it too, with a bare `-1`. Refusing here is what turns
/// that into something a holder can act on.
#[test]
fn a_convert_back_over_the_balance_is_refused_before_the_library_sees_it() {
    let fx = Fixture::new();
    let e = entropy64();
    let context = prover::convert_back_context_hash(&fx.account, &fx.issuance, 1, 0).unwrap();
    let inputs = Inputs {
        tx_kind: TxKind::ConvertBack,
        account_id: &fx.account,
        mpt_issuance_id: &fx.issuance,
        tx_context_id: &context,
        entropy64: &e,
    };
    let (r, rho) = randomness::derive_pair(&inputs).unwrap();
    let cb = ConvertBackInputs {
        sk: fx.sender.secret(),
        pk: fx.sender.public(),
        amount: 101,
        balance: 100,
        balance_ciphertext: prover::encrypt(100, fx.sender.public(), &r).unwrap(),
        issuer_pk: *fx.issuer.public(),
        auditor_pk: None,
        context,
    };
    let err = match prover::prepare_convert_back(&cb, &r, &rho) {
        Err(e) => e,
        Ok(_) => panic!("a ConvertBack of 101 against a balance of 100 produced a proof"),
    };
    match err {
        prover::ProverError::Inconsistent(ref d) => {
            assert!(d.contains("101") && d.contains("100"), "the refusal names neither number: {d}")
        }
        other => panic!("expected a refusal naming both numbers, got {other}"),
    }
}

/// §7's pre-sign detection rule, on the Send side.
///
/// A participant ciphertext whose `C₁` is not `r·G` is refused **before** a
/// proof is generated. E-63 executed the attack this prevents: a passive
/// observer recovered the difference between two hidden amounts from a repeated
/// `C₁`, and rippled accepted both transactions.
#[test]
fn a_participant_whose_c1_is_not_r_g_is_refused_before_proving() {
    let fx = Fixture::new();
    let e = entropy64();
    let context = prover::send_context_hash(&fx.account, &fx.issuance, 1, &fx.dest_account, 0).unwrap();
    let inputs = Inputs {
        tx_kind: TxKind::Send,
        account_id: &fx.account,
        mpt_issuance_id: &fx.issuance,
        tx_context_id: &context,
        entropy64: &e,
    };
    let (r, _rho) = randomness::derive_pair(&inputs).unwrap();
    let other = randomness::derive(
        &Inputs { entropy64: &entropy64(), ..inputs },
        randomness::Role::ElgamalR,
    )
    .unwrap();

    let good = prover::Participant {
        pubkey: *fx.sender.public(),
        ciphertext: prover::encrypt(5, fx.sender.public(), &r).unwrap(),
    };
    // Encrypted under a different scalar: a different C1, and the difference
    // between two amounts becomes recoverable if this ever ships.
    let bad = prover::Participant {
        pubkey: *fx.destination.public(),
        ciphertext: prover::encrypt(5, fx.destination.public(), &other).unwrap(),
    };

    assert!(prover::assert_shared_c1(&[good], &r).is_ok());
    let err = prover::assert_shared_c1(&[good, bad], &r).unwrap_err();
    assert!(matches!(err, prover::ProverError::Inconsistent(_)), "{err}");
}

/// §7's pre-sign rule for the types that **publish** `r` on chain.
#[test]
fn a_blinding_factor_field_that_is_not_the_derived_r_is_refused() {
    let e = entropy64();
    let inputs = Inputs {
        tx_kind: TxKind::Convert,
        account_id: &[0x11; 20],
        mpt_issuance_id: &[0x33; 24],
        tx_context_id: &[0x44; 32],
        entropy64: &e,
    };
    let r = randomness::derive(&inputs, randomness::Role::ElgamalR).unwrap();
    assert!(prover::assert_published_blinding_factor(r.as_bytes(), &r).is_ok());

    let mut tampered = *r.as_bytes();
    tampered[31] ^= 1;
    assert!(prover::assert_published_blinding_factor(&tampered, &r).is_err());
}
